/// <summary>
/// PaffH 17.04.25
/// </summary>
/// <param name="sender">xFormRun</param>
/// <param name="e">FormEventArgs</param>
[FormEventHandler(formStr(NDXPOPspecificDataManagement), FormEventType::Initializing)]
public static void NDXPOPspecificDataManagement_OnInitializing(xFormRun sender, FormEventArgs e)
{
    FormRun formRun = sender as FormRun;
    if (formRun)
    {
        OfficeFormRunHelper officeHelper = formRun.officeHelper();
        if (officeHelper)
        {
            officeHelper.OfficeMenuInitializing += eventhandler(NDXPOPspecificDataManagement_frm_EventHandler::officeMenuInitializingHandler);
        }
    }
}

/// <summary>
/// PaffH 17.04.25
/// </summary>
/// <param name = "_formRun">FormRun</param>
/// <param name = "_eventArgs">OfficeMenuEventArgs</param>
private static void officeMenuInitializingHandler(FormRun _formRun, OfficeMenuEventArgs _eventArgs)
{

    OfficeMenuOptions menuOptions = _eventArgs.menuOptions();
    OfficeMenuDataEntityOptions entityOptions = menuOptions.getOptionsForEntity(tableStr(NDXPOPspecificDataManagementLineTransferEntity));
    if (!entityOptions)
    {
        entityOptions = OfficeMenuDataEntityOptions::construct(tableStr(NDXPOPspecificDataManagementLineTransferEntity));
        menuOptions.dataEntityOptions().addEnd(entityOptions);
    }
}

/// <summary>
/// PaffH 24.03.25
/// </summary>
/// <param name="sender"></param>
/// <param name="e"></param>
[FormDataSourceEventHandler(formDataSourceStr(NDXPOPspecificDataManagement, NDXPOPspecificDataManagementLine), FormDataSourceEventType::DisplayOptionInitialize)]
public static void NDXPOPspecificDataManagementLine_OnDisplayOptionInitialize(FormDataSource sender, FormDataSourceEventArgs e)
{
    FormDataSourceDisplayOptionInitializeEventArgs eventArgs = e as FormDataSourceDisplayOptionInitializeEventArgs;
    NDXPOPspecificDataManagementLine nDXPOPspecificDataManagementLine = eventArgs.record();
    NDXPOPspecificDataManagementHeader nDXPOPspecificDataManagementHeader = NDXPOPspecificDataManagementHeader::findRecId(nDXPOPspecificDataManagementLine.NDXPOPspecificDataManagementHeader, false);

    boolean setColor = true;
    boolean valueChanged = false;
    if (nDXPOPspecificDataManagementLine.CounterErrorMessages)
    {
        int yellow = WinAPI::RGB2int(255,255,182);
        int red = WinAPI::RGB2int(223,13,13);
        eventArgs.displayOption().textColor(yellow);
        eventArgs.displayOption().backColor(red);
    }
    else
    {
        setColor = setColor && nDXPOPspecificDataManagementHeader.MarkedChange == NoYes::No || nDXPOPspecificDataManagementLine.Marked == NoYes::Yes;
        if (setColor)
        {
            valueChanged = valueChanged || nDXPOPspecificDataManagementLine.reqGroupIdChange(nDXPOPspecificDataManagementHeader);
            valueChanged = valueChanged || nDXPOPspecificDataManagementLine.inventItemPurchDefaultChange(nDXPOPspecificDataManagementHeader);
            valueChanged = valueChanged || nDXPOPspecificDataManagementLine.inventItemInventDefaultChange(nDXPOPspecificDataManagementHeader);
            valueChanged = valueChanged || nDXPOPspecificDataManagementLine.inventItemSalesDefaultChange(nDXPOPspecificDataManagementHeader);
            valueChanged = valueChanged || nDXPOPspecificDataManagementLine.inventItemPurchChange(nDXPOPspecificDataManagementHeader);
            valueChanged = valueChanged || nDXPOPspecificDataManagementLine.inventItemInventChange(nDXPOPspecificDataManagementHeader);
            valueChanged = valueChanged || nDXPOPspecificDataManagementLine.inventItemSalesChange(nDXPOPspecificDataManagementHeader);
        }
        setColor = setColor && valueChanged;
        if (setColor)
        {
            eventArgs.displayOption().textColor(WinAPI::RGB2int(121,221,228));
        }
    }
}

/// <summary>
/// PaffH 24.03.25
/// </summary>
/// <param name = "_formRun">FormRun</param>
/// <returns>NDXPOPspecificDataManagementFormI</returns>
protected static NDXPOPspecificDataManagementFormI getNDXPOPspecificDataManagementForm(FormRun _formRun)
{
    NDXPOPspecificDataManagementFormI nDXPOPspecificDataManagementForm;
    if (_formrun is NDXPOPspecificDataManagementFormI)
    {
        nDXPOPspecificDataManagementForm = _formrun as NDXPOPspecificDataManagementFormI;
    }
    else
    {
        error(strFmt("@NDXBase:NDXFormDontImplementInterface", _formrun.name(), SysDictClass::newName(classStr(NDXPOPspecificDataManagementFormI)).name()));
    }
    return nDXPOPspecificDataManagementForm;
}

